source=ROOT/'content'/'Apostila_AWS_AI_Practitioner_AIF-C01_Completa.md'
s=source.read_text(encoding='utf-8')
import io
start=s.find('\n# 27. Simulado original comentado')
end=s.find('\n# 29. Laboratórios guiados')
prefix=s if start<0 else s[:start]
suffix='' if end<0 else s[end:]
with io.StringIO() as f:
 f.write('# 27. Simulado original comentado — 80 questões\n\n> **Nomes completos nesta página:** artificial intelligence (**AI**); machine learning (**ML**); generative AI (**GenAI**); foundation model (**FM**).\n**[PRÁTICA — todos os domínios]**\n\nOs itens abaixo foram redigidos para este curso; **não** são questões oficiais ou cópias de dumps. A quantidade por domínio aproxima os pesos do guia: 16/19/23/11/11. A prática contém questões de escolha única (o exame real também pode ter ordenação, associação e múltiplas respostas). Não converta percentual de acertos em nota 700 da AWS.\n\n## Parte A — questões\n\n')
 for q in qdata:
  f.write(f"### {q['id']} · Domínio {q['domain']}\n\n**{q['prompt']}**\n\n")
  for letter,opt in zip('ABCD',q['choices']):f.write(f'- **{letter}.** {opt}\n')
  f.write('\n')
 f.write('## Parte B — gabarito comentado\n\n')
 for q in qdata:f.write(f"**{q['id']} — {q['correct']}.** {q['explanation']}\n\n")
 f.write('---\n\n# 28. Flashcards para revisão ativa — 120 cartões\n\n> **Nomes completos nesta página:** artificial intelligence (**AI**); machine learning (**ML**); foundation model (**FM**).\n**[REVISÃO ATIVA — todos os domínios]**\n\nTente responder antes de abrir o verso em sua própria prática. Sugestão: rever cartões errados no dia seguinte, hesitados após três dias e dominados após sete dias.\n\n')
 for card in fdata:f.write(f"### {card['id']} — {card['front']}\n\n**Verso:** {card['back']}\n\n")
 source.write_text(prefix+'\n'+f.getvalue()+suffix,encoding='utf-8')
print('questions',len(qdata),'domains',counts,'flashcards',len(fdata),'markdown',source.stat().st_size)
